WITH valid AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, status, DATE_TRUNC('WEEK', delivered_date) AS delivered_date_period, DATE_SUB(delivered_date, 6) AS delivered_date_minus_6d FROM shipments WHERE shipped_date >= DATE '2023-06-26' AND carrier IS DISTINCT FROM 'Flash'), gaps AS (SELECT *, CASE WHEN delivered_date_period - LAG(delivered_date_period) OVER (PARTITION BY order_id ORDER BY delivered_date_period ASC, id ASC) > INTERVAL 60 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM valid), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY delivered_date_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps), deduped AS (SELECT id, order_id, carrier, shipped_date, delivered_date, cost, delivered_date_period, delivered_date_minus_6d, session_start_flag, session_no FROM islands QUALIFY ROW_NUMBER() OVER (PARTITION BY status, carrier ORDER BY session_no ASC, id ASC) = 1), kept_keys AS (SELECT carrier, order_id FROM deduped INTERSECT SELECT carrier, order_id FROM shipments WHERE order_id IS NOT NULL), verified AS (SELECT s.* FROM deduped s INNER JOIN kept_keys k ON s.carrier = k.carrier AND s.order_id = k.order_id), with_windows AS (SELECT carrier, cost, session_start_flag, SUM(session_no) OVER (ORDER BY CAST(delivered_date_period AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS session_no_sum_90d, MAX(session_no) OVER (PARTITION BY order_id, carrier) AS order_id_max_session_no, PERCENT_RANK() OVER (PARTITION BY order_id ORDER BY session_start_flag ASC NULLS FIRST) AS session_start_flag_percent_rank FROM verified WHERE carrier IN ('Kerry', 'DHL', 'Flash')), valid_shipments AS (SELECT carrier, cost, session_no_sum_90d, session_start_flag_percent_rank, CASE WHEN cost >= 73 THEN 'High' WHEN cost >= 17 THEN 'Medium' ELSE 'Low' END AS cost_band, LENGTH(carrier) AS carrier_length FROM with_windows WHERE carrier IS DISTINCT FROM 'UPS'), base AS (SELECT carrier, cost, session_start_flag_percent_rank, cost_band, carrier_length, ROUND(carrier_length * 1.07, 2) AS carrier_length_adjusted, session_no_sum_90d / NULLIF(session_start_flag_percent_rank, 0) AS session_no_sum_90d_per_session_start_flag_percent_rank FROM valid_shipments WHERE carrier IS NOT NULL), summary AS (SELECT CASE WHEN carrier_length >= 81 THEN 'HIGH' ELSE 'LOW' END AS carrier_length_tier, SUM(CASE WHEN carrier = 'Flash' THEN cost ELSE 0 END) AS flash_cost, SIZE(COLLECT_SET(carrier)) AS num_carriers, ROUND(AVG(cost), 2) AS avg_cost, MIN(carrier_length_adjusted) AS min_carrier_length_adjusted, COUNT(CASE WHEN carrier = 'Kerry' THEN 1 END) AS kerry_count FROM base GROUP BY CASE WHEN carrier_length >= 81 THEN 'HIGH' ELSE 'LOW' END HAVING avg_cost < 1000000) SELECT carrier_length_tier, avg_cost, min_carrier_length_adjusted, kerry_count FROM summary ORDER BY avg_cost DESC NULLS FIRST;
